#!/usr/bin/env python3
"""Compute deterministic ground truth for CSX-224_Q1."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-224_Q1"
EVENT_ID = "CSX-224"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT_PATH = TASK_DIR / "computed_gt.json"

SOURCE_FILES = [
    "metadata/event.json",
    "data/other/other_001_NASA_Earth_Observatory_Freetown_landslide.html",
    "data/exposure_impact/exposure_impact_001_HDX_CKAN_package_search.json",
    "data/exposure_impact/exposure_impact_005_salvaged_existing_stage8_file.json",
    "data/physical_hazard/physical_hazard_002_NASA_POWER_daily_point_sample.json",
    "data/physical_hazard/physical_hazard_006_salvaged_existing_stage8_file.json",
]


def read_json(rel_path: str) -> dict[str, Any]:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8"))


def html_text(rel_path: str) -> str:
    raw = (PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="ignore")
    text = re.sub(r"<script\b.*?</script>", " ", raw, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    return html.unescape(re.sub(r"\s+", " ", text))


def first_number(pattern: str, text: str, cast: type = float) -> Any:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return cast(match.group(1).replace(",", ""))


def hdx_notes() -> str:
    hdx = read_json("data/exposure_impact/exposure_impact_001_HDX_CKAN_package_search.json")
    return " ".join(item.get("notes", "") for item in hdx["result"]["results"])


def compact_size(value: dict[str, Any]) -> int:
    return len(json.dumps(value, ensure_ascii=True, separators=(",", ":")))


def cap(value: float, denominator: float) -> float:
    return min(value / denominator, 1.0)


def rounded_metrics() -> dict[str, Any]:
    anchor_text = html_text("data/other/other_001_NASA_Earth_Observatory_Freetown_landslide.html")
    notes = hdx_notes()
    power = read_json("data/physical_hazard/physical_hazard_002_NASA_POWER_daily_point_sample.json")
    era5 = read_json("data/physical_hazard/physical_hazard_006_salvaged_existing_stage8_file.json")
    worldpop = read_json("data/exposure_impact/exposure_impact_005_salvaged_existing_stage8_file.json")

    return {
        "point_precip_mm": round(float(power["properties"]["parameter"]["PRECTOTCORR"]["20170814"]), 2),
        "areal_precip_mm": round(float(era5["stats"]["precipitation_sum_mm_mean"]), 2),
        "path_length_km": round(first_number(r"main Regent landslide event is ([\d.]+) km long", notes), 2),
        "damaged_structures": first_number(r"identify ([\d,]+) damaged structure", notes, int),
        "damaged_roads_km": round(first_number(r"and ([\d.]+) km of damaged roads", notes), 2),
        "deaths_lower_bound": first_number(r"More than ([\d,]+) people died", anchor_text, int),
        "people_lost_homes": first_number(r"and ([\d,]+) people lost their homes", anchor_text, int),
        "forest_decline_percent": first_number(r"([0-9]+) percent decline", anchor_text, int),
        "local_population": round(float(worldpop["population_sum"]["population"])),
    }


def score_ledger(metrics: dict[str, Any]) -> dict[str, Any]:
    components = {
        "precip_pair": (
            0.6 * cap(metrics["point_precip_mm"], 200.0)
            + 0.4 * cap(metrics["areal_precip_mm"], 100.0)
        ),
        "path": cap(metrics["path_length_km"], 5.0),
        "damage": (
            0.7 * cap(metrics["damaged_structures"], 300.0)
            + 0.3 * cap(metrics["damaged_roads_km"], 1.0)
        ),
        "loss": (
            0.55 * cap(metrics["deaths_lower_bound"], 1000.0)
            + 0.45 * cap(metrics["people_lost_homes"], 3000.0)
        ),
        "context": (
            0.5 * cap(metrics["forest_decline_percent"], 60.0)
            + 0.5 * cap(metrics["local_population"], 1000000.0)
        ),
    }

    scores = {
        "rain_runout_loss": 100.0
        * (
            0.30 * components["precip_pair"]
            + 0.25 * components["path"]
            + 0.20 * components["damage"]
            + 0.15 * components["loss"]
            + 0.10 * components["context"]
        ),
        "rain_only": 100.0
        * (
            0.75 * components["precip_pair"]
            + 0.10 * (1.0 - components["path"])
            + 0.10 * (1.0 - components["damage"])
            + 0.05 * (1.0 - components["loss"])
        ),
        "loss_only": 100.0
        * (
            0.75 * components["loss"]
            + 0.15 * (1.0 - components["precip_pair"])
            + 0.10 * (1.0 - components["path"])
        ),
        "context_only": 100.0
        * (
            0.65 * components["context"]
            + 0.15 * (1.0 - components["precip_pair"])
            + 0.10 * (1.0 - components["path"])
            + 0.10 * (1.0 - components["loss"])
        ),
    }

    rounded_components = {key: round(value, 3) for key, value in components.items()}
    rounded_scores = {key: round(value, 2) for key, value in scores.items()}
    score_values = sorted(rounded_scores.values(), reverse=True)
    best_label = max(rounded_scores, key=rounded_scores.get)

    return {
        "components": rounded_components,
        "candidate_scores": rounded_scores,
        "best_label": best_label,
        "second_best_score": score_values[1],
        "margin_to_second": round(score_values[0] - score_values[1], 2),
    }


def build_result() -> dict[str, Any]:
    event = read_json("metadata/event.json")
    metrics = rounded_metrics()
    ledger = score_ledger(metrics)
    interpretation = (
        "The score ledger favors rain_runout_loss because rainfall, path, damage, "
        "and loss components all reach their caps while the context component is lower."
    )

    primary_gt = {
        "target_family": "candidate_score_ledger",
        "metrics": metrics,
        "components": ledger["components"],
        "candidate_scores": ledger["candidate_scores"],
        "best_label": ledger["best_label"],
        "margin_to_second": ledger["margin_to_second"],
        "interpretation": interpretation,
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Output label and JSON shape",
                "points": 3,
                "description": "Returns compact JSON with target_family, metrics, components, candidate_scores, best_label, margin_to_second, and interpretation; best_label is rain_runout_loss.",
                "partial_credit": "Award 1-2 points for the right label with one missing field or minor naming drift.",
            },
            {
                "name": "Package value extraction",
                "points": 4,
                "description": "Extracts the precipitation, path, damage, loss, forest, and population values from the local package.",
                "partial_credit": "Award credit value by value; small rounding differences are acceptable for continuous quantities.",
            },
            {
                "name": "Component formulas",
                "points": 4,
                "description": "Computes precip_pair, path, damage, loss, and context using the stated caps and weights.",
                "partial_credit": "Award 1 point for each mostly correct component; reduce credit for missing caps or swapped weights.",
            },
            {
                "name": "Candidate score formulas",
                "points": 4,
                "description": "Applies all four candidate formulas using unrounded component values, then rounds final candidate scores to two decimals.",
                "partial_credit": "Award partial credit for correct formulas with arithmetic or rounding errors in one or two candidates.",
            },
            {
                "name": "Comparison arithmetic",
                "points": 3,
                "description": "Identifies the second-best score as 75.0 and computes a 24.33 point margin.",
                "partial_credit": "Award 1-2 points for the correct best label with an incorrect or missing margin.",
            },
            {
                "name": "Computed interpretation",
                "points": 2,
                "description": "Explains the result as a formula outcome from saturated rainfall, path, damage, and loss components, not as a broad narrative.",
                "partial_credit": "Award 1 point for a concise statement that names the best label but omits the component reason.",
            },
        ],
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "candidate_score_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "expected_output": {
                "target_family": "candidate_score_ledger",
                "metrics": metrics,
                "components": ledger["components"],
                "candidate_scores": ledger["candidate_scores"],
                "best_label": ledger["best_label"],
                "margin_to_second": ledger["margin_to_second"],
                "interpretation": interpretation,
            },
            "score_details": {
                "second_best_score": ledger["second_best_score"],
                "component_rounding_policy": "Components are reported to three decimals, but candidate scores are computed from unrounded component values and then rounded to two decimals.",
            },
            "source_date_note": {
                "event_precipitation_anchor_date": "2017-08-14",
                "hdx_unosat_note_date": "2017-08-15",
                "interpretation": "The ledger uses the package precipitation/event anchor date for rainfall metrics and treats the HDX date as product/source metadata for damage/path evidence.",
            },
            "formula_thresholds": {
                "point_precip_mm": 200,
                "areal_precip_mm": 100,
                "path_length_km": 5,
                "damaged_structures": 300,
                "damaged_roads_km": 1,
                "deaths_lower_bound": 1000,
                "people_lost_homes": 3000,
                "forest_decline_percent": 60,
                "local_population": 1000000,
            },
        },
        "numeric_tolerances": {
            "point_precip_mm": {"value": metrics["point_precip_mm"], "tolerance": 0.05},
            "areal_precip_mm": {"value": metrics["areal_precip_mm"], "tolerance": 0.05},
            "path_length_km": {"value": metrics["path_length_km"], "tolerance": 0.05},
            "damaged_roads_km": {"value": metrics["damaged_roads_km"], "tolerance": 0.05},
            "margin_to_second": {"value": ledger["margin_to_second"], "tolerance": 0.02},
        },
        "judge_anchors": {
            "canonical_stance": "The deterministic ledger returns rain_runout_loss with a 24.33 point margin over the next score.",
            "required_elements": [
                "Use all nine extracted package metrics.",
                "Apply the capped component formulas before candidate scores; compute scores from unrounded components.",
                "Report rain_runout_loss as the best label.",
                "Keep the final statement tied to the numeric ledger.",
            ],
            "do_not_add": [
                "new casualty estimates",
                "policy advice",
                "field validation conclusions",
                "source material outside the local package",
            ],
        },
        "rubric": rubric,
        "quality_checks": {
            "primary_gt_top_level_keys": len(primary_gt),
            "primary_gt_compact_bytes": compact_size(primary_gt),
            "rubric_criteria_count": len(rubric["criteria"]),
            "rubric_total_points": sum(item["points"] for item in rubric["criteria"]),
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "package_id": event["package_id"],
            "event_name": event["event_name"],
            "source_files": SOURCE_FILES,
            "notes": "Candidate scores are computed from unrounded component values and rounded only at the final score step. HDX/UNOSAT notes reference 15 August imagery/product metadata; precipitation and event metrics use the package's 14 August event anchor.",
        },
    }


def main() -> None:
    OUT_PATH.write_text(
        json.dumps(build_result(), indent=2, sort_keys=True, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
